using System.Collections;
using UnityEngine;

public class LevelGenerator
{
	public delegate void LevelGeneratedEventHandler();

	private static EnemyDecorator _enemyDecorator;

	private static float failsafeTime = 10f;

	private static float lastLoadTime;

	public static LevelGeneratedEventHandler levelGeneratedEventHandlers;

	private static int loadingScreenMsgIndex;

	private static string loadingScreenMsgBase = "<color=#333333>";

	private static string loadingScreenMsgInactive = string.Empty;

	private static string loadingScreenMsgActive = string.Empty;

	public static EnemyDecorator EnemyDecorator
	{
		get
		{
			if (_enemyDecorator == null)
			{
				_enemyDecorator = new EnemyDecorator();
			}
			return _enemyDecorator;
		}
	}

	public static void UpdateLastLoadTime()
	{
		lastLoadTime = Time.time - lastLoadTime;
		failsafeTime = failsafeTime * 0.8f + lastLoadTime * 0.2f;
	}

	public static IEnumerator Generate(MonoBehaviour inst, int width = 512, int height = 512)
	{
		EnemyDecorator.InitializeDecorator();
		Level.prevElement = Level.element;
		bool layoutGeneratorStarted = false;
		bool layoutGeneratorComplete = false;
		string sceneName = Application.loadedLevelName;
		GameController.loadingScreen.SetPromptText(string.Empty);
		GameController.pauseTimer = true;
		loadingScreenMsgInactive = loadingScreenMsgBase;
		loadingScreenMsgActive = string.Empty;
		loadingScreenMsgIndex = 0;
		UpdateLoadingScreenMessage();
		yield return null;
		int levelStopwatchID = -1;
		while (!layoutGeneratorComplete)
		{
			if (LayoutGenerator.forceQuitGenerate)
			{
				if (LayoutGenerator.isGenerating)
				{
					yield return null;
				}
				LayoutGenerator.forceQuitGenerate = false;
				Debug.Log("Error creating floor. Retrying...");
				if (Level.levelContainer != null && Level.levelContainer.gameObject != null)
				{
					Object.Destroy(Level.levelContainer.gameObject);
				}
				LayoutGenerator.ClearLists();
				layoutGeneratorStarted = false;
				layoutGeneratorComplete = false;
				GameController.loadingScreen.SetPromptText(string.Empty);
				loadingScreenMsgInactive = loadingScreenMsgBase;
				loadingScreenMsgActive = string.Empty;
				loadingScreenMsgIndex = 0;
				UpdateLoadingScreenMessage();
				yield return null;
			}
			if (!layoutGeneratorStarted)
			{
				Level.levelContainer = new GameObject("LevelContainer").transform;
				Level.tileGrid = new TileGrid(width, height);
				Level.totalEnemyCount = 0;
				Level.enemiesDefeatedCount = 0;
				Level.totalEnemyCount = 0;
				Level.enemiesDefeatedCount = 0;
				LayoutGenerator.StartGenerator(inst, Level.tileGrid);
				layoutGeneratorStarted = true;
				levelStopwatchID = ChaosStopwatch.Begin(failsafeTime * 1.75f);
				lastLoadTime = Time.time;
			}
			else if (!LayoutGenerator.isGenerating)
			{
				layoutGeneratorComplete = true;
			}
			else if (!LayoutGenerator.ConnectionsExist || ChaosStopwatch.Check(levelStopwatchID))
			{
				if (Level.levelContainer != null && Level.levelContainer.gameObject != null)
				{
					Object.Destroy(Level.levelContainer.gameObject);
				}
				LayoutGenerator.forceQuitGenerate = true;
				UpdateLastLoadTime();
			}
			if (!LayoutGenerator.forceQuitGenerate && sceneName != Application.loadedLevelName)
			{
				LayoutGenerator.forceQuitGenerate = true;
				yield break;
			}
			yield return null;
		}
		UpdateLastLoadTime();
		UpdateLoadingScreenMessage();
		yield return null;
		Level.tileGrid.FinalizeTerrain();
		UpdateLoadingScreenMessage();
		inst.StartCoroutine(OverlayGenerator.GenerateOverlay(Level.tileGrid, 8));
		while (OverlayGenerator.overlayGenerationInProgress)
		{
			yield return null;
		}
		UpdateLoadingScreenMessage();
		yield return null;
		DecorationApplier.ApplyAllDecorations(Level.levelContainer.transform, Level.tileGrid);
		yield return null;
		OrganicPathGenerator.GenerateOrganicPaths(Level.tileGrid, TileSet.Factory(Level.tileSetName));
		yield return null;
		UpdateLoadingScreenMessage();
		yield return null;
		Decorator.DecorateByTileSet(Level.tileSetName, Level.tileGrid, DecorationMode.Global);
		yield return null;
		UpdateLoadingScreenMessage();
		yield return null;
		EnemyDecorator.DecorateTupleList(Level.GridRoomTupleList);
		yield return null;
		UpdateLoadingScreenMessage();
		yield return null;
		for (int i = 0; i < Level.GridRoomTupleList.Count; i++)
		{
			Room second = Level.GridRoomTupleList[i].Second;
			if (second.randomInteractables || second.type == RoomType.FloorPlan)
			{
				Decorator.DecorateByTileSet(Level.tileSetName, Level.GridRoomTupleList[i].First, DecorationMode.Room, second);
			}
		}
		yield return null;
		HallwayDecorator.DecorateByTileSet(Level.tileSetName, Level.GridHallTupleList);
		yield return null;
		Decorator.DecorateByTileSet(Level.tileSetName, Level.tileGrid, DecorationMode.Global, null, 1);
		yield return null;
		Decoration.ClearGlobalPositions();
		yield return null;
		UpdateLoadingScreenMessage();
		yield return null;
		Level.tileGrid.InitLayerVertices(forceVertexUpdate: true, string.Empty);
		yield return null;
		WallGenerator.GenerateWalls(Level.tileGrid, Level.levelContainer.transform);
		yield return null;
		MeshGenerator.GenerateMeshes(Level.tileGrid, Level.levelContainer.transform, string.Empty);
		yield return null;
		PitGenerator.GeneratePits(Level.tileGrid, Level.levelContainer.transform);
		yield return null;
		CheckpointGenerator.GenerateCheckpoints(Level.tileGrid, Level.levelContainer.transform);
		yield return null;
		SetMinMaxPositions();
		yield return null;
		GameController.minimap.InitStageVars(Level.tileGrid);
		yield return null;
		inst.StartCoroutine(Pathfinder.GenerateNodeMap(Level.tileGrid));
		yield return null;
		SetStartPosition();
		SetExitAndStorePositions();
		UpdateLoadingScreenMessage();
		yield return Globals.waitForOne;
		if (Level.isBossRushMode)
		{
			foreach (CompassIndicatorTrigger trigger in CompassIndicatorTrigger.Triggers)
			{
				trigger.Activate();
			}
			foreach (MinimapSection minimapSection in MinimapSection.MinimapSections)
			{
				minimapSection.Reveal(collidedWithPlayer: true);
			}
		}
		GameController.loadingScreen.SetPromptText(string.Empty);
		GameController.loadingScreen.FadeOut();
		GameController.pauseTimer = false;
		yield return null;
		if (levelGeneratedEventHandlers != null)
		{
			levelGeneratedEventHandlers();
		}
		yield return null;
	}

	public static void SetStartPosition()
	{
		Vector2 startPosition = Level.startPosition;
		Player[] playerScripts = GameController.playerScripts;
		foreach (Player player in playerScripts)
		{
			if (!(player == null))
			{
				player.transform.position = startPosition;
				player.myOrigin = startPosition;
				player.lastCheckpoint = player.myOrigin;
				player.facingDirection = FacingDirection.Down;
				player.anim.Play("IdleDown");
			}
		}
		Camera.main.transform.position = new Vector3(startPosition.x, startPosition.y, -10f);
	}

	public static void SetExitAndStorePositions()
	{
		foreach (Tuple<TileGridSection, Room> gridRoomTuple in Level.GridRoomTupleList)
		{
			Room second = gridRoomTuple.Second;
			switch (second.type)
			{
			case RoomType.Exit:
				Level.exitPosition = second.transform.Find("Enemies/ExitRoomEventHandler").position;
				break;
			case RoomType.ItemStore:
			{
				Transform transform = second.transform.Find("Interactables/Portal");
				Level.itemStorePortalInPosition = transform.Find("Spawn").position;
				Level.itemStorePortalOutPosition = transform.Find("Exit").position;
				break;
			}
			case RoomType.SkillStore:
			{
				Transform transform = second.transform.Find("Interactables/Portal");
				Level.skillStorePortalInPosition = transform.Find("Spawn").position;
				Level.skillStorePortalOutPosition = transform.Find("Exit").position;
				break;
			}
			case RoomType.Misc:
			{
				Transform transform = second.transform.Find("Interactables/Portal");
				Level.miscRoomPortalInPosition = transform.Find("Spawn").position;
				Level.miscRoomPortalOutPosition = transform.Find("Exit").position;
				break;
			}
			}
		}
		Level.miscRoomFound = (Level.skillStoreFound = (Level.itemStoreFound = (Level.exitFound = Level.isBossRushMode)));
	}

	public static void SetMinMaxPositions()
	{
		TileGrid tileGrid = Level.tileGrid;
		int rowCount = Level.tileGrid.RowCount;
		int colCount = Level.tileGrid.ColCount;
		Vector2 vector = new Vector2((float)rowCount * 0.5f, (float)colCount * 0.5f);
		Vector2 vector2 = vector;
		for (int i = 0; i < rowCount; i++)
		{
			for (int j = 0; j < colCount; j++)
			{
				if (tileGrid[i, j] != null)
				{
					if ((float)i < vector.x)
					{
						vector.x = i;
					}
					else if ((float)i > vector2.x)
					{
						vector2.x = i;
					}
					if ((float)j < vector.y)
					{
						vector.y = j;
					}
					else if ((float)j > vector2.y)
					{
						vector2.y = j;
					}
				}
			}
		}
		Level.minTileGridPosition = new Vector2(vector.y, 0f - vector.x);
		Level.maxTileGridPosition = new Vector2(vector2.y, 0f - vector2.x);
	}

	private static void UpdateLoadingScreenMessage()
	{
		loadingScreenMsgInactive += loadingScreenMsgActive;
		loadingScreenMsgActive = "\n" + TextManager.GetUIText("loadingScreen-generation" + loadingScreenMsgIndex);
		loadingScreenMsgIndex++;
		GameController.loadingScreen.SetProgressText(loadingScreenMsgInactive + "</color>" + loadingScreenMsgActive + " ...");
	}
}

