	public static Tile.FloorType GetFloorType(TileGrid tileGrid, int row, int col, Func<Tile, bool> comparisonFunc)
	{
		if (!tileGrid.IsValidTile(row, col))
		{
			return Tile.FloorType.None;
		}
		MapOrdinalDirections mapOrdinalDirections = CheckAdjacentTiles(row, col, tileGrid, comparisonFunc);
		MapDirections mapDirections = Globals.OrdinalToCardinalDir(mapOrdinalDirections);
		Tile.FloorType floorType = (Tile.FloorType)mapDirections;
		if (floorType == Tile.FloorType.Center)
		{
			if (!mapOrdinalDirections.HasFlag(MapOrdinalDirections.NorthWest))
			{
				return Tile.FloorType.TopLeftCorner;
			}
			if (!mapOrdinalDirections.HasFlag(MapOrdinalDirections.NorthEast))
			{
				return Tile.FloorType.TopRightCorner;
			}
			if (!mapOrdinalDirections.HasFlag(MapOrdinalDirections.SouthWest))
			{
				return Tile.FloorType.BotLeftCorner;
			}
			if (!mapOrdinalDirections.HasFlag(MapOrdinalDirections.SouthEast))
			{
				return Tile.FloorType.BotRightCorner;
			}
		}
		return floorType;
	}

