		if (tileRow < rowCount - 1 && tileCol < colCount - 1 && tileGrid[tileRow + 1, tileCol + 1] != null && tileGrid[tileRow + 1, tileCol + 1].terrain == targetTerrain)
		{
			mapOrdinalDirections |= MapOrdinalDirections.SouthEast;
		}
		if (tileRow > 0 && tileCol > 0 && tileGrid[tileRow - 1, tileCol - 1] != null && tileGrid[tileRow - 1, tileCol - 1].terrain == targetTerrain)
		{
			mapOrdinalDirections |= MapOrdinalDirections.NorthWest;
		}
		if (tileRow > 0 && tileCol < colCount - 1 && tileGrid[tileRow - 1, tileCol + 1] != null && tileGrid[tileRow - 1, tileCol + 1].terrain == targetTerrain)
