public class WeightedRandomizer
{
	public List<WeightedItem> weightedItems;

	public Dictionary<string, WeightedItem> weightedItemsDict;

	public int weightedRange;

	public WeightedRandomizer()
	{
		weightedItems = new List<WeightedItem>();
		weightedItemsDict = new Dictionary<string, WeightedItem>();
	}

	public void Add(WeightedItem newItem)
	{
		weightedItems.Add(newItem);
		weightedItemsDict[newItem.name] = newItem;
		RecalculateWeights();
	}

	public void Remove(WeightedItem rmItem)
	{
		weightedItems.Remove(rmItem);
		weightedItemsDict.Remove(rmItem.name);
		RecalculateWeights();
	}

	public WeightedItem Get(string name)
	{
		return weightedItemsDict[name];
	}

	public void SetWeight(string name, int weight)
	{
		weightedItemsDict[name].weight = weight;
		RecalculateWeights();
	}

	public void Clear()
	{
		weightedItems.Clear();
		weightedItemsDict.Clear();
	}

	public void Print()
	{
		string text = string.Empty;
		foreach (WeightedItem weightedItem in weightedItems)
		{
			string text2 = text;
			text = text2 + weightedItem.name + ": " + weightedItem.weight + "\n";
		}
		Debug.Log(text);
	}

	public void RecalculateWeights()
	{
		int num = 0;
		int num2 = 0;
		foreach (WeightedItem weightedItem in weightedItems)
		{
			weightedItem.groupID = num;
			weightedItem.lowerBound = num2;
			num2 += weightedItem.weight;
			weightedItem.upperBound = num2 - 1;
			num++;
		}
		weightedRange = num2;
	}

	public WeightedItem GetRandomItem()
	{
		int num = Random.Range(0, weightedRange);
		int num2 = 0;
		foreach (WeightedItem weightedItem in weightedItems)
		{
			num2 = weightedItem.groupID;
			if (num <= weightedItem.upperBound)
			{
				return weightedItem;
			}
		}
		return null;
	}

	public int GetRandomGroupID()
	{
		return GetRandomItem()?.groupID ?? 0;
	}
}
