	public static void ResetAvailableSkills()
	{
		currentPlayerSkills.Clear();
		lockedSigList.Clear();
		bool flag = false;
		Player[] activePlayers = GameController.activePlayers;
		foreach (Player player in activePlayers)
		{
			for (int j = 0; j < player.assignedSkills.Length; j++)
			{
				if (player.assignedSkills[j] != null)

				if (player.assignedSkills[j] != null)
				{
					currentPlayerSkills.Add(player.assignedSkills[j].skillID);
				}
			}
			if (flag)
			{
				continue;
			}
			flag = true;
			foreach (Player.SkillState value in player.skillsDict.Values)
			{
				if (value != null && value.element != ElementType.Chaos && value.hasSignatureVariant && !value.signatureUnlocked)
				{
					lockedSigList.Add(value.skillID);
				}
			}
		}
		availableSkillList.Clear();
		lockedSkillList.Clear();
		for (int k = 0; k < maxSkillTier; k++)
		{
			skillTierDict[k].Shuffle();
			for (int num = skillTierDict[k].Count - 1; num >= 0; num--)
			{
				string text = skillTierDict[k][num];
				if (!currentPlayerSkills.Contains(text))
				{
					availableSkillList.Add(text);
					if (!GameDataManager.gameData.CheckSkillDataEntry(text))
					{
						lockedSkillList.Add(text);
					}
				}
			}
			if (lockedSkillList.Count >= 24)
