	public static void ResetAvailableItems()
	{
		HashSet<string> hashSet = new HashSet<string>(completeItemDict.Keys);
		HashSet<string> hashSet2 = new HashSet<string>();
		HashSet<string> hashSet3 = new HashSet<string>();
		hashSet.Remove(Globals.startingItemID);
		hashSet.Remove(PlayerWinItem.staticID);
		lockedItemIDList.Clear();
		for (int i = 0; i < maxItemTier; i++)
		{
			itemTierDict[i].Shuffle();
			for (int j = 0; j < itemTierDict[i].Count; j++)
			{
				if (!Item.IsUnlocked(itemTierDict[i][j]))
				{
					lockedItemIDList.Add(itemTierDict[i][j]);
				}
			}
			if (lockedItemIDList.Count >= 24)
			{
				break;
			}
		}
		cursedHubOnlyItemIDList.Clear();
		foreach (string item in hashSet)
		{
			if (completeItemDict[item].isCursed)
			{
				hashSet2.Add(item);
				hashSet3.Add(item);
				if (completeItemDict[item].hubOnly)
				{
					cursedHubOnlyItemIDList.Add(item);
				}
			}
			else if (!Item.IsUnlocked(item) || completeItemDict[item].combineOnly)
			{
				hashSet3.Add(item);
			}
		}
		hashSet.ExceptWith(hashSet3);
		hashSet3.Clear();
		foreach (string item2 in hashSet2)
		{
			if (completeItemDict[item2].notForSale || completeItemDict[item2].hubOnly)
			{
				hashSet3.Add(item2);
			}
		}
		hashSet2.ExceptWith(hashSet3);
		hashSet3.Clear();
		hashSet.UnionWith(lockedItemIDList);
		foreach (string item3 in hashSet)
		{
			if (completeItemDict[item3].notForSale)
			{
				hashSet3.Add(item3);
			}
		}
		Player[] activePlayers = GameController.activePlayers;
		foreach (Player player in activePlayers)
		{
			foreach (Item value in player.inventory.itemDict.Values)
			{
				if (value == null)
				{
					continue;
				}
				string iD = value.ID;
				hashSet3.Add(iD);
				hashSet2.Remove(iD);
				if (excludeItemDict.ContainsKey(iD))
				{
					hashSet3.UnionWith(excludeItemDict[iD]);
					hashSet2.ExceptWith(excludeItemDict[iD]);
				}
				if (!value.isGroupItem)
				{
					continue;
				}
				GroupItem groupItem = value as GroupItem;
				foreach (string itemID in groupItem.itemInven.GetItemIDList())
				{
					hashSet3.Add(itemID);
				}
			}
		}
		hashSet.ExceptWith(hashSet3);
		availableItemIDList.Clear();
		availableItemIDList = new List<string>(hashSet);
		cursedItemIDList.Clear();
		cursedItemIDList = new List<string>(hashSet2);
		hashSet.Clear();
		hashSet2.Clear();
		hashSet3.Clear();
	}

