	public static void DropSkill(Vector3 spawnLocation, int amount, string skillID = "", float lockedSkillDropRate = 0f, float signatureSkillDropRate = 0f, HashSet<ElementType> elementSet = null, bool useLifeTime = false, bool isEmpowered = false)
	{
		bool flag = signatureSkillDropRate > 0f && signatureSkillDropRate > Random.value;
		for (int i = 0; i < amount; i++)
		{
			string text = string.Empty;
			if (skillID != string.Empty)
			{
				text = skillID;
			}
			else
			{
				if (Random.value > lockedSkillDropRate)
				{
					text = GetSkillID(locked: true, flag);
				}
				if (text == string.Empty)
				{
					bool signature = flag;
					text = GetSkillID(locked: false, signature);
				}
				if (text == string.Empty)
				{
					text = GetSkillID();
				}
			}
			if (text == string.Empty || text == noDropID)
			{
				continue;
			}
			bool flag2 = false;
			Player[] activePlayers = GameController.activePlayers;
			foreach (Player player in activePlayers)
			{
				if (player.skillsDict.ContainsKey(text))
				{
					Player.SkillState skillState = player.skillsDict[text];
					if (flag)
					{
						text = ((!skillState.hasSignatureVariant) ? (text + "Empowered") : (text + "Signature"));
					}
					else if (isEmpowered)
					{
						text += "Empowered";
					}
					flag2 = true;
				}
				if (flag2)
				{
					break;
				}
			}
			if (flag2)
			{
				ItemSpawner itemSpawner = GameController.itemSpawner;
				ItemSpawner.PoolType poolType = ItemSpawner.PoolType.SkillDrop;
				Vector2 spawnLocation2 = spawnLocation;
				string otherValue = text;
				itemSpawner.SpawnItem(poolType, spawnLocation2, randomizeSpawnLocation: true, 1.5f, otherValue, useMinDist: true, useLifeTime);
				SoundManager.PlayAudio("DropSpell");
			}
		}
	}

