public int GoldAmount
{
	get
	{
		tempGoldAmt = 0f;
		if (UnityEngine.Random.value < goldDropRate)
		{
			tempGoldAmt = (float)UnityEngine.Random.Range(minGold, maxGold + 1) * LootManager.globalGoldModifier.ModifiedValue;
			if (goldCompensation)
			{
				tempGoldAmt *= LootManager.GoldCompensationVal;
			}
			else
			{
				LootManager.nonCompensatedGoldVal += Mathf.CeilToInt(tempGoldAmt);
			}
		}
		return Mathf.CeilToInt(tempGoldAmt);
	}
}

public int PlatAmount
