	get
	{
		tempPlatAmt = minPlat;
		tempPlatMult = LootManager.PlatPerStageMultiplier;
		if (UnityEngine.Random.value < platDropRate)
		{
			tempPlatAmt = UnityEngine.Random.Range((minPlat <= 0) ? 1 : minPlat, maxPlat + 1);
		}
		if (tempPlatAmt > 1)
		{
			tempPlatAmt = Mathf.FloorToInt((float)tempPlatAmt * (1f + tempPlatMult));
		}
		else if (tempPlatAmt == 1)
		{
			tempPlatAmt += (int)LootManager.globalPlatModifier.CurrentValue + ((UnityEngine.Random.value < LootManager.PlatPerStageMultiplier) ? 1 : 0);
		}
		return tempPlatAmt;
	}
}

