	public virtual void Load(Player newShopper)
	{
		gameObject.SetActive(value: true);
		shoppers[newShopper.playerID] = newShopper;
	}

	public virtual void Close(Player curShopper)
	{
		curShopper.fsm.ChangeState("Idle");
		shoppers[curShopper.playerID] = null;
		if (shoppers.Count((Player s) => s == null) == GameController.maxPlayerCount)
		{
			gameObject.SetActive(value: false);
		}
	}

